INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"cea549cb-29eb-51ae-a9d2-fabb91d1a8bb","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"cea549cb-29eb-51ae-a9d2-fabb91d1a8bb","title":"桃花坞年画从哪里来","summary":"从苏州画铺认识这一年画传统。","body":"资料要点\n国家级项目档案将桃花坞木版年画的产生记为明代，兴盛记为清代雍正、乾隆时期。它与苏州的年画生产和传播密切相关。\n\n观察练习\n阅读图鉴时，可以分别关注角色、画面题材和印刷技法。应用中的桃夭等角色属于现代原创表达；它们的名字与经历并非这段历史的一部分。","coverAssetId":"9b4907b9-a8b9-5912-a602-c74dab6bf81c","sourceRecords":[{"id":"ich-national","title":"桃花坞木版年画项目档案","publisher":"中国非物质文化遗产网·中国非物质文化遗产数字博物馆","url":"https://www.ihchina.cn/project_details/13902/","accessedAt":"2026-11-10","supports":["明代产生","清雍正乾隆兴盛","2006年第一批国家级项目","项目编号Ⅶ-3"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"8ae7399a-5fab-5d20-aba0-efccd3ced048","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"cea549cb-29eb-51ae-a9d2-fabb91d1a8bb","title":"怎样读懂非遗项目编号","summary":"核对名称、类别、年份和项目编号。","body":"资料要点\n项目档案记载：桃花坞木版年画属于传统美术，2006年列入第一批国家级名录，项目编号为Ⅶ-3。\n\n阅读提示\n文化内容中应把项目名称写完整。应用角色、数字作品与这项传统技艺之间是创意启发关系，不能据此宣称角色获得了非遗认证。查看资料卡中的原始链接，可进一步核对项目说明。","coverAssetId":"f5eda81e-b2ab-5010-a6e3-11f9560cd3bd","sourceRecords":[{"id":"ich-national","title":"桃花坞木版年画项目档案","publisher":"中国非物质文化遗产网·中国非物质文化遗产数字博物馆","url":"https://www.ihchina.cn/project_details/13902/","accessedAt":"2026-11-10","supports":["明代产生","清雍正乾隆兴盛","2006年第一批国家级项目","项目编号Ⅶ-3"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"047c6956-7e4d-5db7-aca6-fbe37925a428","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"cea549cb-29eb-51ae-a9d2-fabb91d1a8bb","title":"画、刻、印怎样协作","summary":"一幅作品背后的三类工作。","body":"资料要点\n地方志资料把制作过程概括为画稿、刻版、套印三个相互衔接的步骤，必要时还会填色或装裱。\n\n创作练习\n在数字工坊里先安排主角，再选择背景与装饰，最后检查色彩和位置。这只是帮助理解分层创作的练习，不是对手工工序的完整模拟。真正的刻版还涉及材料、刀法和实践经验。","coverAssetId":"bb57ff41-861d-51f6-a15c-4c4031b18016","sourceRecords":[{"id":"suzhou-chronicle","title":"苏州的文化艺术——桃花坞木刻年画","publisher":"苏州市地方志编纂委员会办公室","url":"https://dfzb.suzhou.gov.cn/dfzb/szdq/201812/433e74797ff04e7c8891679868be248f.shtml","accessedAt":"2026-11-10","supports":["姑苏版别称","分版分色套印","画稿刻版套印三个步骤"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"47968395-99cc-5545-afdb-e4a003d00600","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"cea549cb-29eb-51ae-a9d2-fabb91d1a8bb","title":"姑苏版与桃花坞年画","summary":"理解称呼背后的地域联系。","body":"资料要点\n苏州市地方志文章介绍，桃花坞曾是江南民间年画生产的重要聚集地，苏州木刻年画也被称作姑苏版或苏州版。\n\n观察练习\n地名可以帮助我们理解作品的生产环境，但不代表所有水乡插画都是传统年画。本应用的水巷、月台和花园背景是当代原创虚构场景，使用时会保留这一说明。","coverAssetId":"6add7827-1358-5c6b-a789-afa288350e27","sourceRecords":[{"id":"suzhou-chronicle","title":"苏州的文化艺术——桃花坞木刻年画","publisher":"苏州市地方志编纂委员会办公室","url":"https://dfzb.suzhou.gov.cn/dfzb/szdq/201812/433e74797ff04e7c8891679868be248f.shtml","accessedAt":"2026-11-10","supports":["姑苏版别称","分版分色套印","画稿刻版套印三个步骤"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"d58bcca2-28e7-522f-a815-b34358b1d759","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"78a908a1-04e7-597a-a84c-3f48fe9a2234","title":"为什么画稿要反向上版","summary":"从方向关系理解上样。","body":"资料要点\n苏州地方志的工艺说明中，上样包含将画稿反向附着到木版上的环节。\n\n观察练习\n可以想象把一张纸翻过来，再与原图比较左右关系。数字工坊的图层仍是正向预览；我们不把拖拽素材称为完成了真实上样。了解方向关系后，再观察画面中的文字或不对称图形，会更容易发现需要检查的位置。","coverAssetId":"58d81c06-ca63-54d4-a42a-461d6406aa6c","sourceRecords":[{"id":"suzhou-craft","title":"跟着总书记看江苏：桃花坞木刻年画原来如此传奇","publisher":"苏州市地方志编纂委员会办公室","url":"https://dfzb.suzhou.gov.cn/dfzb/szdq/202307/5f8473123cc3488e8275cc7233514186.shtml","accessedAt":"2026-11-10","supports":["画刻印分工","上样为反向附稿","工艺传承与文创"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"6473214f-c151-59e1-a3b9-baa73b418d36","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"78a908a1-04e7-597a-a84c-3f48fe9a2234","title":"传承不只保留一幅画","summary":"关注画、刻、印的技艺学习。","body":"资料要点\n相关工艺介绍指出，今天的传承教学注重把画、刻、印的能力一起传授给学习者。\n\n创作提示\n欣赏完成作品时，也可以关心它如何被制作。数字组合创作能提供构图练习，却不能替代手工训练。应用用原创角色降低初次接触的门槛，同时保留资料来源，鼓励继续认识真实技艺。","coverAssetId":"9bb95420-dabb-5aa8-a5ad-a57512106aa6","sourceRecords":[{"id":"suzhou-craft","title":"跟着总书记看江苏：桃花坞木刻年画原来如此传奇","publisher":"苏州市地方志编纂委员会办公室","url":"https://dfzb.suzhou.gov.cn/dfzb/szdq/202307/5f8473123cc3488e8275cc7233514186.shtml","accessedAt":"2026-11-10","supports":["画刻印分工","上样为反向附稿","工艺传承与文创"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"84ba406b-3256-59b0-a5da-a3857a62674d","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"78a908a1-04e7-597a-a84c-3f48fe9a2234","title":"一版一色是什么意思","summary":"把色彩想象成可以分别安排的层。","body":"资料要点\n苏州市政府的文化介绍说明，桃花坞木版年画以彩色套版为主要方式，一版对应一种颜色，并可兼用着色技艺。\n\n工坊练习\n尝试把主角、背景和装饰分开安排，再比较叠加后的整体效果。这里的图层是数字编辑工具，不是传统色版的直接复制；角色换色也不等于形成了新的原创设计。","coverAssetId":"8aff3851-bfda-594d-a752-ea544ada81ed","sourceRecords":[{"id":"suzhou-festival","title":"全国各地非遗年俗集结桃花坞","publisher":"苏州市人民政府","url":"https://www.suzhou.gov.cn/szsrmzf/szyw/202501/7f602a5883644269b70a3e8f141eb025.shtml","accessedAt":"2026-11-10","supports":["一版一色","吉祥喜庆民俗生活戏文花鸟风景题材"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"5c454209-2b50-5a15-a2fa-641be84e2e2b","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"78a908a1-04e7-597a-a84c-3f48fe9a2234","title":"年画里可以画些什么","summary":"从生活、故事和自然寻找主题。","body":"资料要点\n官方介绍列举的题材包括吉祥喜庆、民俗生活、戏文故事、花鸟果蔬与风景名胜等。\n\n创作练习\n先用一句话确定自己的主题，再挑选一个主角和少量装饰。例如以花开为题，可以让花卉与角色形成呼应。这些建议属于本应用的现代设计练习，不为某个图案附加未经证实的历史寓意。","coverAssetId":"52f98146-7d9b-5b25-a9b5-8f2beab753e8","sourceRecords":[{"id":"suzhou-festival","title":"全国各地非遗年俗集结桃花坞","publisher":"苏州市人民政府","url":"https://www.suzhou.gov.cn/szsrmzf/szyw/202501/7f602a5883644269b70a3e8f141eb025.shtml","accessedAt":"2026-11-10","supports":["一版一色","吉祥喜庆民俗生活戏文花鸟风景题材"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"fa9de2ab-08f5-544c-a22a-39b0a779af81","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"d7c24004-8764-5cdf-a7ab-311149f3c443","title":"认识刷墨与擦印","summary":"区分涂墨工具与按压纸张的工具。","body":"资料要点\n苏州图书馆的体验活动记录展示了以棕刷涂墨、覆盖纸张，再用棕擦擦印的过程。\n\n观看提示\n本应用中的器物贴纸采用萌系装饰设计，不能作为传统工具尺寸或结构的技术图。参与线下体验时，应按老师的指导操作；不要根据插画自行判断刀具或印刷工具的安全用法。","coverAssetId":"9439b83f-1961-5858-adb4-9e0a48ff669d","sourceRecords":[{"id":"suzhou-library","title":"苏州古籍保护网木版年画体验活动记录","publisher":"苏州图书馆","url":"https://www.szlib.com/AncientProtection/Home/Details/1210","accessedAt":"2026-11-10","supports":["彩色套版","棕刷棕擦手工体验","常见题材与版式"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"96b1bd42-abbc-528c-aa63-78656959446f","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"d7c24004-8764-5cdf-a7ab-311149f3c443","title":"版式会怎样影响观看","summary":"把画面的用途与形状联系起来。","body":"资料要点\n相关介绍提到门画、中堂和独幅画等形式。作品的使用位置与观看方式，会影响我们理解它的构图。\n\n工坊练习\n本应用首期采用4:5纵向画布。可以把主体放在中间，也可以保留较大的文字空间；无论怎样安排，都应检查角色是否被裁切、文字是否与背景混在一起。此比例是数字产品的设计选择。","coverAssetId":"73efdd0c-1fa5-51de-aef4-f9176b6da4f6","sourceRecords":[{"id":"suzhou-library","title":"苏州古籍保护网木版年画体验活动记录","publisher":"苏州图书馆","url":"https://www.szlib.com/AncientProtection/Home/Details/1210","accessedAt":"2026-11-10","supports":["彩色套版","棕刷棕擦手工体验","常见题材与版式"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"f65079c4-1f3c-5138-a045-5043f5007e7c","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"d7c24004-8764-5cdf-a7ab-311149f3c443","title":"雕版印刷与名录边界","summary":"相关技艺的名录名称需要准确区分。","body":"资料要点\nUNESCO页面记载，中国雕版印刷技艺于2009年列入人类非物质文化遗产代表作名录，介绍了木版雕刻与手工印刷。\n\n阅读提示\n这页资料的对象是中国雕版印刷技艺。它不能直接证明桃花坞木版年画作为同名独立项目在该年入选UNESCO。本应用分别保留来源名称，避免把相关技艺的身份混为一谈。","coverAssetId":"f5eda81e-b2ab-5010-a6e3-11f9560cd3bd","sourceRecords":[{"id":"unesco-print","title":"China engraved block printing technique","publisher":"UNESCO","url":"https://ich.unesco.org/en/RL/china-engraved-block-printing-technique-00229","accessedAt":"2026-11-10","supports":["中国雕版印刷技艺2009年列入代表作名录","木版雕刻与手工印刷流程"],"boundary":"该页面为中国雕版印刷技艺，不能把其名录身份直接等同于桃花坞木版年画单独入选UNESCO","imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
INSERT INTO "thwkb_knowledge_articles" ("id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt") SELECT "id","tenantId","appId","categoryId","title","summary","body","coverAssetId","sourceRecords","factCheckStatus","status","publishedAt","createdAt","updatedAt" FROM jsonb_populate_record(NULL::"thwkb_knowledge_articles",'{"id":"aa3e5f42-71f8-5864-acbc-f52000de4987","tenantId":"thwkb.zh.huawei","appId":"thwkb.zh.huawei","createdAt":"2026-11-11T02:48:03.621Z","updatedAt":"2026-11-11T02:48:03.621Z","categoryId":"d7c24004-8764-5cdf-a7ab-311149f3c443","title":"传统灵感怎样进入今天","summary":"理解文化传承与当代设计的联系。","body":"资料要点\n苏州市政府的介绍提及通过教学、展览、非遗市集和文创等方式推动桃花坞木版年画的传承。\n\n设计提示\n本应用选择重新设计角色比例、服饰、表情和构图，并记录每张图片的来源。桃花、云纹和套色层次是创意线索；我们不会把传统原作加滤镜后称为新角色，也不会把现代故事写成真实史料。","coverAssetId":"72060885-1c54-5649-ae1e-706da04fde52","sourceRecords":[{"id":"suzhou-modern","title":"春节申遗成功：桃花坞木版年画参与申报","publisher":"苏州市人民政府","url":"https://www.suzhou.gov.cn/szsrmzf/szyw/202412/ed0c1d1696634b42b68ce0598eca4695.shtml","accessedAt":"2026-11-10","supports":["国家级名录年份","教学与非遗市集等传承方式"],"imageLicense":"未使用网页图片"}],"factCheckStatus":"verified","status":"published","publishedAt":"2026-11-11T02:48:03.621Z"}'::jsonb) ON CONFLICT ("tenantId","appId",id) DO NOTHING;
